11:   if (first.totalCount > limit) throw new Error(`This range contains more than ${limit.toLocaleString()} records. Narrow the dates to load accurate analytics.`);
12:   const rows = [...first.items];
13:   const pages = Math.ceil(first.totalCount / first.pageSize);
14:   for (let page = 2; page <= pages; page++) {
15:     if (signal?.aborted) throw new Error('Request cancelled.');
16:     const next = await load(page, signal);
17:     if (next.totalCount !== first.totalCount) throw new Error('Billing records changed while loading. Refresh to calculate accurate totals.');
18:     rows.push(...next.items);
19:   }
20:   if (rows.length !== first.totalCount || new Set(rows.map(row => row.id)).size !== rows.length) throw new Error('Incomplete billing response. Refresh and try again.');

